Here's a C function that parallelizes an independent loop using pthreads:

```c
#include <pthread.h>
#include <stdlib.h>
#include <stdio.h>

// Structure to pass parameters to each thread
typedef struct {
    int thread_id;
    int start;
    int end;
    void (*task)(int);  // Function pointer for the task to execute
} ThreadArg;

// Thread function that processes a chunk of the loop
void *thread_func(void *arg) {
    ThreadArg *targ = (ThreadArg *)arg;

    // Execute the task for each item in this thread's range
    for (int i = targ->start; i < targ->end; i++) {
        targ->task(i);
    }

    return NULL;
}

// Main parallel loop function
int parallel_loop(int N, int T, void (*task)(int)) {
    if (N <= 0 || T <= 0) {
        fprintf(stderr, "Error: N and T must be positive\n");
        return -1;
    }

    // Adjust thread count if N < T
    if (T > N) {
        T = N;
    }

    // Allocate arrays for threads and arguments
    pthread_t *threads = (pthread_t *)malloc(T * sizeof(pthread_t));
    ThreadArg *args = (ThreadArg *)malloc(T * sizeof(ThreadArg));

    if (threads == NULL || args == NULL) {
        fprintf(stderr, "Error: Memory allocation failed\n");
        free(threads);
        free(args);
        return -1;
    }

    // Calculate chunk size and create threads
    int chunk_size = N / T;
    int remainder = N % T;

    for (int i = 0; i < T; i++) {
        args[i].thread_id = i;
        args[i].start = i * chunk_size + (i < remainder ? i : remainder);
        args[i].end = (i + 1) * chunk_size + (i + 1 < remainder ? i + 1 : remainder);
        args[i].task = task;

        // Create thread
        if (pthread_create(&threads[i], NULL, thread_func, &args[i]) != 0) {
            fprintf(stderr, "Error: Failed to create thread %d\n", i);

            // Cleanup already created threads
            for (int j = 0; j < i; j++) {
                pthread_cancel(threads[j]);
                pthread_join(threads[j], NULL);
            }

            free(threads);
            free(args);
            return -1;
        }
    }

    // Join all threads
    for (int i = 0; i < T; i++) {
        pthread_join(threads[i], NULL);
    }

    // Clean up
    free(threads);
    free(args);

    return 0;
}

// Example task function
void example_task(int index) {
    // This is where you would put the work for each iteration
    printf("Thread %lu processing item %d\n", pthread_self(), index);

    // Example computation
    volatile double result = 0;
    for (int i = 0; i < 1000000; i++) {
        result += i * index;
    }
}

// Example usage
int main() {
    int N = 100;  // Number of items
    int T = 4;    // Number of threads

    printf("Processing %d items with %d threads\n", N, T);

    int result = parallel_loop(N, T, example_task);

    if (result == 0) {
        printf("Parallel loop completed successfully\n");
    } else {
        printf("Parallel loop failed\n");
    }

    return 0;
}
```

## Key Features:

1. **Thread-safe Work Distribution**: Uses static work distribution where each thread gets a contiguous chunk of work. This is efficient for loops where each iteration has similar computational cost.

2. **Balanced Load**: Handles cases where N isn't divisible by T by distributing remainder iterations among the first few threads.

3. **Error Handling**: Includes comprehensive error handling for:
   - Invalid input parameters
   - Memory allocation failures
   - Thread creation failures
   - Proper cleanup on errors

4. **Flexible Task Interface**: Uses a function pointer to specify the work for each iteration, making it reusable for different parallel loops.

5. **Resource Management**: Properly allocates and frees all memory, and joins all threads before returning.

## Usage Notes:

1. **Function Pointer**: The `task` function must be thread-safe (no race conditions). If it accesses shared data, you'll need to add appropriate synchronization.

2. **Thread Count**: If T > N, it automatically adjusts T to N to avoid creating idle threads.

3. **Compilation**: Compile with `-pthread` flag: `gcc -pthread -o parallel_loop parallel_loop.c`

4. **Customization**: You can modify the `thread_func` to handle different work distribution strategies (dynamic, guided, etc.) if needed.

