#include <stdio.h>
#include <stdlib.h>
#include <string.h>
#include <ctype.h>

/**
 * Tokenizes a string by whitespace into an array of strings.
 * The input string is not modified.
 * 
 * @param str Input string to tokenize
 * @return Array of strings (tokens), NULL-terminated. 
 *         Caller must free using free_token_array().
 *         Returns NULL if str is NULL or no tokens found.
 */
char** tokenize_string(const char* str) {
    if (str == NULL || *str == '\0') {
        return NULL;
    }

    // First pass: count the number of tokens
    size_t token_count = 0;
    const char* ptr = str;
    int in_token = 0;

    while (*ptr) {
        if (!isspace((unsigned char)*ptr)) {
            if (!in_token) {
                token_count++;
                in_token = 1;
            }
        } else {
            in_token = 0;
        }
        ptr++;
    }

    if (token_count == 0) {
        return NULL;
    }

    // Allocate array for token pointers (plus NULL terminator)
    char** tokens = malloc((token_count + 1) * sizeof(char*));
    if (tokens == NULL) {
        return NULL;
    }

    // Second pass: extract and copy each token
    size_t token_index = 0;
    ptr = str;

    while (*ptr && token_index < token_count) {
        // Skip whitespace
        while (*ptr && isspace((unsigned char)*ptr)) {
            ptr++;
        }

        if (*ptr == '\0') {
            break;
        }

        // Find end of current token
        const char* token_start = ptr;
        while (*ptr && !isspace((unsigned char)*ptr)) {
            ptr++;
        }

        size_t token_len = ptr - token_start;

        // Allocate and copy token
        tokens[token_index] = malloc(token_len + 1);
        if (tokens[token_index] == NULL) {
            // Free already allocated tokens and array
            free_token_array(tokens);
            return NULL;
        }

        memcpy(tokens[token_index], token_start, token_len);
        tokens[token_index][token_len] = '\0';
        token_index++;
    }

    // NULL terminate the array
    tokens[token_count] = NULL;

    return tokens;
}

/**
 * Frees memory allocated by tokenize_string().
 * Safe to call with NULL.
 * 
 * @param tokens Array of strings to free
 */
void free_token_array(char** tokens) {
    if (tokens == NULL) {
        return;
    }

    // Free each token string
    for (size_t i = 0; tokens[i] != NULL; i++) {
        free(tokens[i]);
    }

    // Free the array itself
    free(tokens);
}

// Example usage and test
int main() {
    const char* test_string = "  Hello   world!  This is a   test.  ";

    printf("Original string: \"%s\"\n\n", test_string);

    char** tokens = tokenize_string(test_string);
    if (tokens == NULL) {
        printf("No tokens found.\n");
        return 1;
    }

    printf("Tokens found:\n");
    for (size_t i = 0; tokens[i] != NULL; i++) {
        printf("  [%zu]: \"%s\"\n", i, tokens[i]);
    }

    // Clean up
    free_token_array(tokens);

    return 0;
}
```

**Key Features:**

1. **Non-destructive**: The input string remains unchanged
2. **Proper memory management**:
   - Allocates memory for both the array and individual token strings
   - Provides `free_token_array()` for cleanup
   - Handles allocation failures gracefully
3. **NULL-terminated array**: The token array ends with a `NULL` pointer
4. **Handles edge cases**:
   - Empty strings
   - Strings with only whitespace
   - Multiple consecutive whitespace characters
   - Leading/trailing whitespace

**Memory Layout Example:**
For the string "  Hello   world!  This is a   test.  ":
