Here's a complete C implementation for converting between UTF-8 and UTF-32 with proper error handling:

```c
#include <stdint.h>
#include <stddef.h>
#include <string.h>

/* Error codes for invalid sequences */
typedef enum {
    UTF8_VALID = 0,
    UTF8_ERROR_SHORT_SEQUENCE,
    UTF8_ERROR_INVALID_CONTINUE,
    UTF8_ERROR_OVERLONG,
    UTF8_ERROR_INVALID_CODEPOINT,
    UTF8_ERROR_ENCODE_FAILURE
} UTF8Error;

/* Structure to hold UTF-32 codepoint with error info */
typedef struct {
    uint32_t codepoint;
    UTF8Error error;
    size_t bytes_consumed;
} UTF32Result;

/* Structure to hold UTF-8 sequence with error info */
typedef struct {
    uint8_t bytes[4];
    size_t length;
    UTF8Error error;
} UTF8Result;

/* Helper function to check if a byte is a valid UTF-8 continuation byte */
static int is_continuation(uint8_t byte) {
    return (byte & 0xC0) == 0x80;
}

/* Helper function to check if a codepoint is in valid Unicode range */
static int is_valid_codepoint(uint32_t cp) {
    /* Check for valid Unicode range (0 to 0x10FFFF) and exclude surrogates */
    return (cp <= 0x10FFFF) && 
           ((cp < 0xD800) || (cp > 0xDFFF)) &&
           ((cp < 0xFDD0) || (cp > 0xFDEF)) &&
           (cp != 0xFFFE) && (cp != 0xFFFF);
}

/* Helper function to get the number of bytes needed for a codepoint */
static size_t get_utf8_length(uint32_t codepoint) {
    if (codepoint <= 0x7F) return 1;
    if (codepoint <= 0x7FF) return 2;
    if (codepoint <= 0xFFFF) return 3;
    if (codepoint <= 0x10FFFF) return 4;
    return 0; /* Invalid codepoint */
}

/* Convert a UTF-8 sequence to a UTF-32 codepoint */
UTF32Result utf8_to_utf32(const uint8_t *utf8, size_t max_length) {
    UTF32Result result = {0, UTF8_VALID, 0};

    if (!utf8 || max_length == 0) {
        result.error = UTF8_ERROR_SHORT_SEQUENCE;
        return result;
    }

    uint8_t first_byte = utf8[0];

    /* Determine sequence length from first byte */
    size_t sequence_length;
    uint32_t mask;

    if (first_byte <= 0x7F) {
        /* 1-byte sequence (ASCII) */
        sequence_length = 1;
        mask = 0x7F;
    } else if ((first_byte & 0xE0) == 0xC0) {
        /* 2-byte sequence */
        sequence_length = 2;
        mask = 0x1F;
    } else if ((first_byte & 0xF0) == 0xE0) {
        /* 3-byte sequence */
        sequence_length = 3;
        mask = 0x0F;
    } else if ((first_byte & 0xF8) == 0xF0) {
        /* 4-byte sequence */
        sequence_length = 4;
        mask = 0x07;
    } else {
        /* Invalid leading byte */
        result.error = UTF8_ERROR_SHORT_SEQUENCE;
        return result;
    }

    /* Check if we have enough bytes */
    if (max_length < sequence_length) {
        result.error = UTF8_ERROR_SHORT_SEQUENCE;
        return result;
    }

    /* Check for overlong sequences */
    uint32_t codepoint = first_byte & mask;

    if (sequence_length == 2 && codepoint < 0x02) {
        result.error = UTF8_ERROR_OVERLONG;
        return result;
    }
    if (sequence_length == 3 && codepoint < 0x10) {
        result.error = UTF8_ERROR_OVERLONG;
        return result;
    }
    if (sequence_length == 4 && codepoint < 0x01) {
        result.error = UTF8_ERROR_OVERLONG;
        return result;
    }

    /* Process continuation bytes */
    for (size_t i = 1; i < sequence_length; i++) {
        if (!is_continuation(utf8[i])) {
            result.error = UTF8_ERROR_INVALID_CONTINUE;
            return result;
        }
        codepoint = (codepoint << 6) | (utf8[i] & 0x3F);
    }

    /* Validate codepoint range */
    if (!is_valid_codepoint(codepoint)) {
        result.error = UTF8_ERROR_INVALID_CODEPOINT;
        return result;
    }

    /* Check for UTF-16 surrogates */
    if (codepoint >= 0xD800 && codepoint <= 0xDFFF) {
        result.error = UTF8_ERROR_INVALID_CODEPOINT;
        return result;
    }

    result.codepoint = codepoint;
    result.bytes_consumed = sequence_length;

    return result;
}

/* Convert a UTF-32 codepoint to a UTF-8 sequence */
UTF8Result utf32_to_utf8(uint32_t codepoint) {
    UTF8Result result = {0, 0, UTF8_VALID};

    if (!is_valid_codepoint(codepoint)) {
        result.error = UTF8_ERROR_ENCODE_FAILURE;
        return result;
    }

    if (codepoint <= 0x7F) {
        /* 1-byte sequence (ASCII) */
        result.bytes[0] = (uint8_t)codepoint;
        result.length = 1;
    } else if (codepoint <= 0x7FF) {
        /* 2-byte sequence */
        result.bytes[0] = 0xC0 | (codepoint >> 6);
        result.bytes[1] = 0x80 | (codepoint & 0x3F);
        result.length = 2;
    } else if (codepoint <= 0xFFFF) {
