        result.bytes[0] = 0xE0 | (codepoint >> 12);
        result.bytes[1] = 0x80 | ((codepoint >> 6) & 0x3F);
        result.bytes[2] = 0x80 | (codepoint & 0x3F);
        result.length = 3;
    } else if (codepoint <= 0x10FFFF) {
        /* 4-byte sequence */
        result.bytes[0] = 0xF0 | (codepoint >> 18);
        result.bytes[1] = 0x80 | ((codepoint >> 12) & 0x3F);
        result.bytes[2] = 0x80 | ((codepoint >> 6) & 0x3F);
        result.bytes[3] = 0x80 | (codepoint & 0x3F);
        result.length = 4;
    } else {
        result.error = UTF8_ERROR_ENCODE_FAILURE;
    }

