    }

    UTF32Result result = utf8_to_utf32((const uint8_t *)utf8, strlen(utf8));

    if (bytes_consumed) *bytes_consumed = result.bytes_consumed;
    *codepoint = result.codepoint;

    return result.error;
}

/* Convenience function for UTF-32 to UTF-8 (writes to buffer and returns length) */
int utf32_to_utf8_simple(uint32_t codepoint, char *utf8, size_t buffer_size) {
    if (!utf8 || buffer_size == 0) return UTF8_ERROR_ENCODE_FAILURE;

    UTF8Result result = utf32_to_utf8(codepoint);

    if (result.error != UTF8_VALID) {
        utf8[0] = '\0';
        return result.error;
    }

    /* Check if buffer is large enough */
    if (result.length + 1 > buffer_size) {
        utf8[0] = '\0';
        return UTF8_ERROR_ENCODE_FAILURE;
    }

    memcpy(utf8, result.bytes, result.length);
    utf8[result.length] = '\0'; /* Null terminate */

    return (int)result.length;
}

