#include <stdint.h>
#include <stddef.h>
#include <stdbool.h>

// Reads a varint from buffer at position *cursor, advancing cursor by the number of bytes read.
// Returns true if successful, false if buffer too short or varint exceeds 64 bits.
static bool read_varint(const uint8_t* buffer, size_t buffer_size, size_t* cursor, uint64_t* result) {
    if (cursor == NULL || result == NULL || buffer == NULL) {
        return false;
    }

    *result = 0;
    int shift = 0;

    while (1) {
        // Bounds check
        if (*cursor >= buffer_size) {
            return false;  // Unexpected end of buffer
        }

        uint8_t byte = buffer[*cursor];
        *cursor += 1;

        // Check if this is the last byte (MSB is 0)
        if ((byte & 0x80) == 0) {
            // Check for overflow
            if (shift > 63 && (byte & 0x7F) > 0) {
                return false;  // Would overflow uint64_t
            }

            *result |= ((uint64_t)(byte & 0x7F)) << shift;
            return true;
        } else {
            // Not the last byte, continue reading
            // Check for overflow before shifting
            if (shift > 63) {
                return false;  // Too many bytes for uint64_t
            }

            // Store the low 7 bits
            *result |= ((uint64_t)(byte & 0x7F)) << shift;
            shift += 7;
        }
    }
}

// Reads a little-endian uint64 and a varint from buffer, advancing cursor.
// Returns true if successful, false if buffer too short or invalid data.
bool read_uint64_and_varint(
    const uint8_t* buffer,
    size_t buffer_size,
    size_t* cursor,
    uint64_t* out_uint64,
    uint64_t* out_varint
) {
    if (buffer == NULL || cursor == NULL || out_uint64 == NULL || out_varint == NULL) {
        return false;
    }

    // Check if we have enough bytes for uint64 (8 bytes)
    if (*cursor + 8 > buffer_size) {
        return false;  // Not enough bytes for uint64
    }

    // Read little-endian uint64
    *out_uint64 = 0;
    for (int i = 0; i < 8; i++) {
        *out_uint64 |= ((uint64_t)buffer[*cursor + i]) << (8 * i);
    }
    *cursor += 8;

    // Read varint
    if (!read_varint(buffer, buffer_size, cursor, out_varint)) {
        // If varint reading fails, cursor might have been advanced
        // depending on where the error occurred
        return false;
    }

    return true;
}

// Example usage
#ifdef EXAMPLE_USAGE
#include <stdio.h>
#include <string.h>

int main() {
    // Example buffer: 8 bytes for uint64 + 3 bytes for varint
    uint8_t buffer[] = {
        0x01, 0x02, 0x03, 0x04, 0x05, 0x06, 0x07, 0x08,  // uint64 LE: 0x0807060504030201
        0xC8, 0x01,                                         // varint: 200 (128 + 72)
        0x00                                                // Additional padding
    };

    size_t buffer_size = sizeof(buffer);
    size_t cursor = 0;
    uint64_t uint64_val, varint_val;

    if (read_uint64_and_varint(buffer, buffer_size, &cursor, &uint64_val, &varint_val)) {
        printf("uint64: 0x%016llX\n", (unsigned long long)uint64_val);
        printf("varint: %llu\n", (unsigned long long)varint_val);
        printf("cursor position after read: %zu\n", cursor);
    } else {
        printf("Failed to read values\n");
    }

    return 0;
}
#endif
```

**Key features:**

1. **Bounds checking**: The function validates buffer boundaries before each read operation
2. **Little-endian uint64 reading**: Correctly interprets 8 bytes in little-endian order
3. **Varint decoding**: Supports Protocol Buffers-style varints (7 bits per byte, MSB continuation flag)
4. **Cursor advancement**: Updates the cursor position only after successful reads
5. **Overflow protection**: Prevents reading values that exceed 64-bit capacity
6. **Error handling**: Returns false if buffer is too short or data is invalid

**Varint format explanation:**
- Each byte uses 7 bits for data and 1 bit (MSB) as continuation flag
- MSB = 1 means more bytes follow, MSB = 0 means last byte
- Example: varint 200 is encoded as `0xC8 0x01` (128 + 72 = 200)
- Maximum 10 bytes for a 64-bit value

**Usage notes:**
- `buffer` must point to valid data with at least `buffer_size` bytes
- `cursor` should point to a `size_t` variable initialized to the starting offset
- `out_uint64` and `out_varint` receive the decoded values
- Returns `true` on success, `false` on failure
- Cursor advances by 8 bytes (for uint64) plus the number of varint bytes read

