```c
#include <stdlib.h>
#include <string.h>
#include <ctype.h>
#include <stdio.h>

typedef enum {
    TOKEN_LBRACE,
    TOKEN_RBRACE,
    TOKEN_LBRACKET,
    TOKEN_RBRACKET,
    TOKEN_COLON,
    TOKEN_COMMA,
    TOKEN_STRING,
    TOKEN_NUMBER,
    TOKEN_TRUE,
    TOKEN_FALSE,
    TOKEN_NULL,
    TOKEN_ERROR,
    TOKEN_EOF
} TokenType;

typedef struct {
    TokenType type;
    size_t start;
    size_t length;
} Token;

typedef struct {
    Token *tokens;
    size_t count;
    size_t capacity;
    const char *input;
    size_t pos;
} Tokenizer;

void init_tokenizer(Tokenizer *t, const char *input) {
    t->input = input;
    t->pos = 0;
    t->count = 0;
    t->capacity = 16;
    t->tokens = malloc(t->capacity * sizeof(Token));
}

void add_token(Tokenizer *t, TokenType type, size_t start, size_t length) {
    if (t->count >= t->capacity) {
        t->capacity *= 2;
        t->tokens = realloc(t->tokens, t->capacity * sizeof(Token));
    }

    t->tokens[t->count].type = type;
    t->tokens[t->count].start = start;
    t->tokens[t->count].length = length;
    t->count++;
}

void skip_whitespace(Tokenizer *t) {
    while (t->input[t->pos] == ' ' || t->input[t->pos] == '\t' || 
           t->input[t->pos] == '\n' || t->input[t->pos] == '\r') {
        t->pos++;
    }
}

Token* tokenize_json(const char *input, size_t *token_count) {
    Tokenizer t;
    init_tokenizer(&t, input);

    while (t.input[t.pos] != '\0') {
        skip_whitespace(&t);

        if (t.input[t.pos] == '\0') break;

        char c = t.input[t.pos];

        if (c == '{') {
            add_token(&t, TOKEN_LBRACE, t.pos, 1);
            t.pos++;
        } else if (c == '}') {
            add_token(&t, TOKEN_RBRACE, t.pos, 1);
            t.pos++;
        } else if (c == '[') {
            add_token(&t, TOKEN_LBRACKET, t.pos, 1);
            t.pos++;
        } else if (c == ']') {
            add_token(&t, TOKEN_RBRACKET, t.pos, 1);
            t.pos++;
        } else if (c == ':') {
            add_token(&t, TOKEN_COLON, t.pos, 1);
            t.pos++;
        } else if (c == ',') {
            add_token(&t, TOKEN_COMMA, t.pos, 1);
            t.pos++;
        } else if (c == '"') {
            // String
            size_t start = t.pos;
            t.pos++; // skip opening quote

            while (t.input[t.pos] != '\0' && t.input[t.pos] != '"') {
                if (t.input[t.pos] == '\\') {
                    t.pos++; // skip escaped character
                }
                t.pos++;
            }

            if (t.input[t.pos] == '"') {
                t.pos++; // skip closing quote
                add_token(&t, TOKEN_STRING, start, t.pos - start);
            } else {
                // Unterminated string
                add_token(&t, TOKEN_ERROR, start, t.pos - start);
            }
        } else if (c == '-' || isdigit(c)) {
            // Number
            size_t start = t.pos;

            if (c == '-') t.pos++;

            // Integer part
            if (t.input[t.pos] == '0') {
                t.pos++;
            } else if (isdigit(t.input[t.pos])) {
                while (isdigit(t.input[t.pos])) t.pos++;
            } else {
                add_token(&t, TOKEN_ERROR, start, t.pos - start);
                continue;
            }

            // Fractional part
            if (t.input[t.pos] == '.') {
                t.pos++;
                if (!isdigit(t.input[t.pos])) {
                    add_token(&t, TOKEN_ERROR, start, t.pos - start);
                    continue;
                }
                while (isdigit(t.input[t.pos])) t.pos++;
            }

            // Exponent part
            if (t.input[t.pos] == 'e' || t.input[t.pos] == 'E') {
                t.pos++;
                if (t.input[t.pos] == '+' || t.input[t.pos] == '-') {
                    t.pos++;
                }
                if (!isdigit(t.input[t.pos])) {
                    add_token(&t, TOKEN_ERROR, start, t.pos - start);
                    continue;
                }
                while (isdigit(t.input[t.pos])) t.pos++;
            }

            add_token(&t, TOKEN_NUMBER, start, t.pos - start);
        } else if (isalpha(c)) {
            // Literals (true, false, null)
            size_t start = t.pos;

            if (strncmp(&t.input[t.pos], "true", 4) == 0) {
                t.pos += 4;
                add_token(&t, TOKEN_TRUE, start, 4);
            } else if (strncmp(&t.input[t.pos], "false", 5) == 0) {
                t.pos += 5;
                add_token(&t, TOKEN_FALSE, start, 5);
            } else if (strncmp(&t.input[t.pos], "null", 4) == 0) {
                t.pos += 4;
                add_token(&t, TOKEN_NULL, start, 4);
            } else {
                // Unknown identifier
                while (isalpha(t.input[t.pos])) t.pos++;
                add_token(&t, TOKEN_ERROR, start, t.pos - start);
            }
        } else {
            // Invalid character
            add_token(&t, TOKEN_ERROR, t.pos, 1);
            t.pos++;
        }
    }

    // Add EOF token
    add_token(&t, TOKEN_EOF, t.pos, 0);

    *token_count = t.count;
    return t.tokens;
}

void free_tokens(Token *tokens) {
    free(tokens);
}

// Example usage
void print_token_type(TokenType type) {
    switch (type) {
        case TOKEN_LBRACE: printf("LBRACE"); break;
        case TOKEN_RBRACE: printf("RBRACE"); break;
        case TOKEN_LBRACKET: printf("LBRACKET"); break;
        case TOKEN_RBRACKET: printf("RBRACKET"); break;
        case TOKEN_COLON: printf("COLON"); break;
        case TOKEN_COMMA: printf("COMMA"); break;
        case TOKEN_STRING: printf("STRING"); break;
        case TOKEN_NUMBER: printf("NUMBER"); break;
        case TOKEN_TRUE: printf("TRUE"); break;
        case TOKEN_FALSE: printf("FALSE"); break;
        case TOKEN_NULL: printf("NULL"); break;
        case TOKEN_ERROR: printf("ERROR"); break;
        case TOKEN_EOF: printf("EOF"); break;
    }
}

int main() {
    const char *json = "{\"name\": \"John\", \"age\": 30, \"active\": true}";

    size_t token_count;
    Token *tokens = tokenize_json(json, &token_count);

    printf("Tokens (%zu):\n", token_count);
    for (size_t i = 0; i < token_count; i++) {
        printf("%zu: Type=", i);
        print_token_type(tokens[i].type);
        printf(", Start=%zu, Length=%zu, Text=\"",
               tokens[i].start, tokens[i].length);

        // Print the actual text
        for (size_t j = 0; j < tokens[i].length; j++) {
            printf("%c", json[tokens[i].start + j]);
        }
        printf("\"\n");
    }

    free_tokens(tokens);
    return 0;
}
```

## Key Features:

1. **Token Types**: Defines 13 token types (7 structural, 5 value, 1 error, 1 EOF)
2. **Token Structure**: Each token contains type, start position, and length
3. **Error Handling**: Catches unterminated strings, invalid numbers, and unknown identifiers
4. **Escape Sequence Handling**: Properly handles backslash escapes in strings
5. **Complete Number Parsing**: Handles integers, decimals, and exponents
6. **Memory Management**: Dynamic array that grows as needed
7. **Minimal Dependencies**: Only uses standard C library functions

