#include <stdlib.h>
#include <string.h>
#include <unistd.h>
#include <sys/socket.h>
#include <netinet/in.h>
#include <arpa/inet.h>

#define PORT 8080
#define BUFFER_SIZE 1024

// Helper function to clean up and close a socket safely
void close_socket(int *sockfd) {
    if (*sockfd != -1) {
        close(*sockfd);
        *sockfd = -1;
    }
}

int main() {
    int server_fd, client_fd = -1;
    struct sockaddr_in server_addr, client_addr;
    socklen_t addr_len = sizeof(client_addr);
    char buffer[BUFFER_SIZE];
    ssize_t bytes_read;

    // Create TCP socket
    server_fd = socket(AF_INET, SOCK_STREAM, 0);
    if (server_fd == -1) {
        perror("socket creation failed");
        return EXIT_FAILURE;
    }

    // Set socket options to allow address reuse
    int opt = 1;
    if (setsockopt(server_fd, SOL_SOCKET, SO_REUSEADDR, &opt, sizeof(opt)) == -1) {
        perror("setsockopt failed");
        close_socket(&server_fd);
        return EXIT_FAILURE;
    }

    // Configure server address
    memset(&server_addr, 0, sizeof(server_addr));
    server_addr.sin_family = AF_INET;
    server_addr.sin_addr.s_addr = INADDR_ANY;
    server_addr.sin_port = htons(PORT);

    // Bind socket to address
    if (bind(server_fd, (struct sockaddr *)&server_addr, sizeof(server_addr)) == -1) {
        perror("bind failed");
        close_socket(&server_fd);
        return EXIT_FAILURE;
    }

    // Start listening
    if (listen(server_fd, 1) == -1) {
        perror("listen failed");
        close_socket(&server_fd);
        return EXIT_FAILURE;
    }

    printf("Echo server listening on port %d...\n", PORT);

    // Server loop: handle one client at a time
    while (1) {
        // Accept incoming connection
        client_fd = accept(server_fd, (struct sockaddr *)&client_addr, &addr_len);
        if (client_fd == -1) {
            perror("accept failed");
            continue;  // Continue accepting other clients
        }

        printf("Client connected: %s:%d\n", 
               inet_ntoa(client_addr.sin_addr), 
               ntohs(client_addr.sin_port));

        // Echo loop: read data from client and send it back
        while ((bytes_read = read(client_fd, buffer, BUFFER_SIZE - 1)) > 0) {
            buffer[bytes_read] = '\0';  // Null-terminate for printing

            // Echo the received data back to client
            if (write(client_fd, buffer, bytes_read) != bytes_read) {
                perror("write failed");
                break;
            }

            printf("Echoed %zd bytes\n", bytes_read);
        }

        // Check for read errors
        if (bytes_read == -1) {
            perror("read failed");
        } else {
            printf("Client disconnected\n");
        }

        // Clean up client connection
        close_socket(&client_fd);
    }

    // Cleanup server socket (unreachable in this simple example)
    close_socket(&server_fd);
    return EXIT_SUCCESS;
}
```

## Key Features:

1. **Proper Resource Management**:
   - Uses `close_socket()` helper to safely close file descriptors
   - Sets file descriptors to `-1` after closing to prevent double-close

2. **Robust Error Handling**:
   - Checks all system calls for errors
   - Cleans up properly on any failure
   - Continues accepting clients even if one connection fails

3. **Graceful Shutdown**:
   - Handles client disconnection cleanly
   - Detects end-of-file (client closing connection)
   - Handles both read and write errors

4. **POSIX Compliant**:
   - Uses standard POSIX socket APIs
   - Compatible with Linux, macOS, and other Unix-like systems

## Usage:

1. Compile: `gcc -o echo_server echo_server.c`
2. Run: `./echo_server`
3. Test with: `telnet localhost 8080` or `nc localhost 8080`
4. Type text and see it echoed back

## Important Notes:

- This server handles only one client at a time (blocking model)
- It will block waiting for a client to disconnect before accepting the next one
- The server runs indefinitely until terminated (Ctrl+C)
- Uses port 8080 by default (change `PORT` macro to use a different port)

The server demonstrates proper socket programming patterns including cleanup on all error paths, which is crucial for production code to avoid resource leaks.

Here's a memory-efficient Node.js function that reads a large file line by line using `readline`, counts lines that fail JSON parsing, and never loads the entire file into RAM.

### ✅ Key design choices:
- **`fs.createReadStream`** + **`readline.createInterface`** → true streaming, one line at a time
- **`for await...of`** on the readline interface → clean async iteration with automatic backpressure handling
- **`JSON.parse()` in a try/catch** → catches malformed JSON without affecting the stream
- **No arrays, `split()`, or `readFileSync`** → constant memory usage regardless of file size

### 📦 Function

```javascript
const fs = require('fs');
const readline = require('readline');

/**
 * Counts JSON parse errors in a large file, reading line by line.
 * @param {string} filePath - Path to the file
 * @param {object} [options] - Optional settings
 * @param {boolean} [options.skipEmptyLines=false] - Skip blank lines instead of counting as errors
 * @returns {Promise<number>} - Total count of lines that failed JSON parsing
 */
async function countJsonParseErrors(filePath, { skipEmptyLines = false } = {}) {
  const rl = readline.createInterface({
    input: fs.createReadStream(filePath, { encoding: 'utf8' }),
    crlfDelay: Infinity // treat \r\n as line break on any platform
  });

  let errorCount = 0;

  for await (const line of rl) {
    // Optionally skip truly empty lines
    if (skipEmptyLines && line.trim() === '') continue;

    try {
      JSON.parse(line);
    } catch (e) {
      // Line is not valid JSON
      errorCount++;
    }
  }

  return errorCount;
}

// 👇 Example usage
// countJsonParseErrors('large-data.json')
//   .then(count => console.log(`JSON parse errors found: ${count}`))
//   .catch(err => console.error('Failed to read file:', err));
```

### 🔍 How it works
| Step | What happens |
|------|--------------|
| `fs.createReadStream` | Starts streaming the file in fixed-size chunks (default ~64KB) |
| `readline.createInterface` | Buffers only **one line** at a time from the chunk stream |
| `for await (const line of rl)` | Yields each line on demand; Node handles backpressure & closing automatically |
| `JSON.parse(line)` | If it throws → increment error counter |
| Return `errorCount` | Final tally, computed without ever assembling the whole file in memory |

### 💡 Notes
- **Empty lines**: By default, an empty string `''` fails `JSON.parse()` and gets counted. Set `skipEmptyLines: true` to ignore them.
- **Encoding**: The stream is created with `{ encoding: 'utf8' }` so lines come as plain strings.
- **Error handling**: The function rejects if the file doesn't exist or isn't readable—handle with `.catch()` or `try...catch` at the call site.
- **Platform**: `crlfDelay: Infinity` ensures `\r\n` line endings work cross-platform.

This pattern scales to multi-gigabyte files with **O(1) memory footprint** per line.
